import re

def guardrail_entrada(prompt_usuario: str) -> bool:
    patrones_sospechosos = [r"ignore previous instructions", r"olvida tus instrucciones", r"system prompt"]
    for pat in patrones_sospechosos:
        if re.search(pat, prompt_usuario, re.IGNORECASE):
            return False # Bloquear peticion
    return True

