import re

def redactar_secretos(texto_salida: str) -> str:
    # Mascara para claves estilo sk-...
    patron_sk = r"sk-[a-zA-Z0-9]{20,}"
    return re.sub(patron_sk, "[SECRET_REDACTED]", texto_salida)
